/**
 * agent-browser-viewer — host half.
 *
 * Serves the newest screenshot of the agent's headless browser to the Web page
 * over two same-origin routes, so the Client half (a right-Sidebar tab) can
 * poll it without a Remote namespace of its own:
 *
 * - `GET /agent-browser-view/state`      → JSON metadata of the newest PNG
 * - `GET /agent-browser-view/latest.png` → those bytes, `no-store`
 *
 * Both routes pass the composition's Host/Origin fence and browser
 * authentication before answering, exactly like the shipped route owners do.
 */
import { readdir, readFile, stat } from 'node:fs/promises';
import { join, resolve } from 'node:path';

/** Loader row id, for diagnostics. */
export const name = 'agent-browser-view';

/** The composition's HTTP server and its authenticated-request fence. */
export const inject = ['webServer', 'connection'];

/** Metadata route path. */
const STATE_PATH = '/agent-browser-view/state';
/** Image route path. */
const IMAGE_PATH = '/agent-browser-view/latest.png';
/** Default screenshot directory: the dsh-browser tool writes here under this workspace. */
const DEFAULT_DIR = '/mnt/Documents/browser-screenshots';

/** The composition's connection service (its package type is not a Host dependency here). */
function connectionOf(ctx) {
  return Reflect.get(ctx, 'connection');
}

/** The newest `.png` in `dir`, or undefined when the directory is missing or empty. */
async function newestShot(dir) {
  const names = await readdir(dir).catch(() => []);
  let best;
  for (const name of names) {
    if (!/\.png$/i.test(name)) continue;
    const path = join(dir, name);
    const info = await stat(path).catch(() => undefined);
    if (info === undefined || !info.isFile()) continue;
    if (best === undefined || info.mtimeMs > best.mtimeMs) {
      best = { path, name, bytes: info.size, mtimeMs: info.mtimeMs };
    }
  }
  return best;
}

/** Answer an untrusted/unauthenticated request; true when it was rejected. */
function rejected(ctx, req, res) {
  const rejection = connectionOf(ctx)?.requestRejection(req);
  if (rejection === undefined || rejection === null) return false;
  res.statusCode = rejection;
  res.end();
  return true;
}

/** Method fence shared by both GET-only routes. */
function rejectedMethod(req, res) {
  if (req.method === 'GET') return false;
  res.statusCode = 405;
  res.setHeader('allow', 'GET');
  res.end();
  return true;
}

/**
 * Register the two viewer routes for the plugin's lifetime.
 * @param ctx - Host context carrying the webserver and the connection fence.
 * @param config - this row's config; `dir` overrides the screenshot directory.
 */
export function apply(ctx, config = {}) {
  const dir = resolve(config.dir ?? DEFAULT_DIR);

  ctx.effect(() => ctx.webServer.register({
    kind: 'exact',
    path: STATE_PATH,
    handler: async (req, res) => {
      if (rejected(ctx, req, res) || rejectedMethod(req, res)) return;
      const shot = await newestShot(dir);
      res.statusCode = 200;
      res.setHeader('content-type', 'application/json; charset=utf-8');
      res.setHeader('cache-control', 'no-store');
      res.end(JSON.stringify({
        dir,
        exists: shot !== undefined,
        name: shot?.name,
        path: shot?.path,
        bytes: shot?.bytes,
        mtimeMs: shot?.mtimeMs,
      }));
    },
  }), `agent-browser-viewer: GET ${STATE_PATH}`);

  ctx.effect(() => ctx.webServer.register({
    kind: 'exact',
    path: IMAGE_PATH,
    handler: async (req, res) => {
      if (rejected(ctx, req, res) || rejectedMethod(req, res)) return;
      const shot = await newestShot(dir);
      if (shot === undefined) {
        res.statusCode = 404;
        res.end();
        return;
      }
      const bytes = await readFile(shot.path).catch(() => undefined);
      if (bytes === undefined) {
        res.statusCode = 404;
        res.end();
        return;
      }
      res.statusCode = 200;
      res.setHeader('content-type', 'image/png');
      res.setHeader('content-length', String(bytes.byteLength));
      res.setHeader('cache-control', 'no-store');
      res.end(bytes);
    },
  }), `agent-browser-viewer: GET ${IMAGE_PATH}`);
}
